import {editorRequest} from './project-browser.js';
import {validBuildProfile} from './build-profile.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export class BuildPanel{
  constructor(element,{session,openScenes,saveAll,error}){this.element=element;this.hooks={session,openScenes,saveAll,error};this.selected='windows';this.unload=event=>{if(this.dirty){event.preventDefault();event.returnValue='';}};window.addEventListener('beforeunload',this.unload);this.load().catch(error);}
  async request(url,data,method='POST'){return (await editorRequest(url,data===undefined?{}:{method,headers:{'Content-Type':'application/json'},body:JSON.stringify(data)})).json();}
  async load(){this.data=await this.request('/api/build/profiles');this.files=(await this.request('/api/project?recursive=1')).entries.filter(f=>f.kind==='scene');if(!this.data.profiles.some(p=>p.id===this.selected))this.selected=this.data.profiles[0].id;this.dirty=false;this.render();}
  render(){const e=this.element,p=this.data.profiles.find(p=>p.id===this.selected),running=this.job?.status==='running';e.className='build-panel';e.innerHTML=`<aside><header><strong>빌드 프로필</strong><button data-build="delete-profile" title="선택 프로필 삭제" aria-label="선택 프로필 삭제" ${this.data.profiles.length===1?'disabled':''}>−</button><button data-build="duplicate" title="프로필 복제" aria-label="프로필 복제">+</button></header>${this.data.profiles.map(p=>`<button class="${p.id===this.selected?'active':''}" data-profile="${p.id}">${esc(p.name)}<small>Windows x64</small></button>`).join('')}</aside><section><header><h2>${esc(p.name)}</h2><span>Windows x64</span></header><div class="build-fields"><label>프로필 이름<input data-field="name" value="${esc(p.name)}" maxlength="80"></label><label>게임 이름<input data-field="productName" value="${esc(p.productName)}" maxlength="80"></label><label>구성<select data-field="configuration"><option value="development" ${p.configuration==='development'?'selected':''}>개발</option><option value="release" ${p.configuration==='release'?'selected':''}>배포</option></select></label><label>창 크기<div class="build-size"><input type="number" data-field="width" aria-label="게임 창 너비" min="320" max="7680" value="${p.width}"><span>×</span><input type="number" data-field="height" aria-label="게임 창 높이" min="240" max="4320" value="${p.height}"></div></label></div><div class="build-scenes-heading"><h3>장면</h3><button data-build="add-open">열린 장면 추가</button></div><div class="build-scene-list">${p.scenes.map((s,i)=>`<div draggable="true" data-scene="${i}"><input type="checkbox" data-enabled="${i}" ${s.enabled?'checked':''} aria-label="${esc(s.path)} 포함"><span title="${esc(s.path)}">${esc(s.path)}${s.enabled&&i===p.scenes.findIndex(s=>s.enabled)?'<small>시작 장면</small>':''}</span><button data-up="${i}" ${i===0?'disabled':''} aria-label="${esc(s.path)} 위로">↑</button><button data-down="${i}" ${i===p.scenes.length-1?'disabled':''} aria-label="${esc(s.path)} 아래로">↓</button><button data-remove="${i}" aria-label="${esc(s.path)} 제거">×</button></div>`).join('')}</div><div class="build-add"><select aria-label="빌드에 추가할 장면"><option value="">장면 선택</option>${this.files.filter(f=>!p.scenes.some(s=>s.path===f.path)).map(f=>`<option value="${esc(f.path)}">${esc(f.path)}</option>`).join('')}</select><button data-build="add">추가</button></div><div class="build-progress" role="status"></div><pre class="build-result" tabindex="0"></pre><div class="build-output" ${this.job?.status==='done'&&this.job.result?.executable?'':'hidden'}><button data-build="run">게임 실행</button><button data-build="reveal">출력 폴더</button></div><footer><span>${this.dirty?'저장하지 않은 변경':''}</span><button data-build="reload" ${running?'disabled':''}>다시 읽기</button><button data-build="save" ${running?'disabled':''}>프로필 저장</button><button data-build="validate" ${running?'disabled':''}>검사</button><button class="primary" data-build="build" ${running?'disabled':''}>모두 저장하고 빌드</button><button data-build="build-run" ${running?'disabled':''}>빌드 후 실행</button><button data-build="cancel" ${running?'':'hidden'}>취소</button></footer></section>`;
    this.renderJob();e.oninput=event=>{const input=event.target;if(input.dataset.field){const key=input.dataset.field;p[key]=input.type==='number'?Number(input.value):input.value;this.dirty=true;this.element.querySelector('footer>span').textContent='저장하지 않은 변경';if(key==='name'){this.element.querySelector('h2').textContent=p.name;this.element.querySelector('[data-profile="'+p.id+'"]').firstChild.textContent=p.name;}return;}};e.onchange=event=>{const input=event.target;if(input.dataset.enabled!==undefined)p.scenes[Number(input.dataset.enabled)].enabled=input.checked;else return;this.dirty=true;this.render();};
    e.onclick=event=>{const b=event.target.closest('button');if(!b)return;const run=async()=>{if(b.dataset.profile){this.selected=b.dataset.profile;return this.render();}for(const [key,delta] of [['up',-1],['down',1]])if(b.dataset[key]!==undefined){const i=Number(b.dataset[key]);[p.scenes[i],p.scenes[i+delta]]=[p.scenes[i+delta],p.scenes[i]];this.dirty=true;return this.render();}if(b.dataset.remove!==undefined){p.scenes.splice(Number(b.dataset.remove),1);this.dirty=true;return this.render();}const action=b.dataset.build;if(action==='run'||action==='reveal')return this.request('/api/build/open',{id:this.job.id,action});if(action==='delete-profile'){if(this.data.profiles.length===1)return;this.data.profiles=this.data.profiles.filter(p=>p.id!==this.selected);this.selected=this.data.profiles[0].id;this.dirty=true;return this.render();}if(action==='reload')return this.load();if(action==='duplicate'){if(this.data.profiles.length>=32)throw Error('프로필은 32개까지 만들 수 있어요.');const copy=structuredClone(p);copy.id='profile_'+crypto.randomUUID().slice(0,8);copy.name=copy.name.slice(0,76)+' 복사';this.data.profiles.push(copy);this.selected=copy.id;this.dirty=true;return this.render();}if(action==='add-open'||action==='add'){const paths=action==='add-open'?this.hooks.openScenes():[e.querySelector('.build-add select').value];for(const path of paths)if(path&&!p.scenes.some(s=>s.path===path))p.scenes.push({path,enabled:true});this.dirty=true;return this.render();}if(action==='save')return this.save();if(action==='cancel'){await this.request('/api/build/cancel',{id:this.job.id});return;}if(action==='validate'||action==='build'||action==='build-run'){if(!this.data.profiles.every(validBuildProfile))throw Error('이름·창 크기·실행할 장면을 확인하세요.');if(action!=='validate'&&!await this.hooks.saveAll())return;await this.save();if(this.dirty)throw Error('저장 중 변경한 빌드 설정을 먼저 저장하세요.');this.job=await this.request('/api/build',{profileId:this.selected,expectedRevision:this.data.revision,dryRun:action==='validate'});this.runAfterBuild=action==='build-run';this.render();this.poll();}};run().catch(this.hooks.error);};
    e.ondragstart=event=>{const row=event.target.closest('[data-scene]');if(row){event.dataTransfer.setData('application/x-hb-build-scene',row.dataset.scene);event.dataTransfer.effectAllowed='move';}};e.ondragover=event=>{if(event.dataTransfer.types.some(t=>['application/x-hb-build-scene','application/x-hb-assets'].includes(t)))event.preventDefault();};e.ondrop=event=>{if(event.dataTransfer.types.includes('application/x-hb-assets')){event.preventDefault();event.stopPropagation();try{for(const f of JSON.parse(event.dataTransfer.getData('application/x-hb-assets')))if(f.kind==='scene'&&!p.scenes.some(s=>s.path===f.path))p.scenes.push({path:f.path,enabled:true});this.dirty=true;this.render();}catch(error){this.hooks.error(error);}return;}if(!event.dataTransfer.types.includes('application/x-hb-build-scene'))return;const row=event.target.closest('[data-scene]');if(!row)return;const from=Number(event.dataTransfer.getData('application/x-hb-build-scene')),to=Number(row.dataset.scene);if(!Number.isInteger(from)||!p.scenes[from])return;event.preventDefault();p.scenes.splice(to,0,p.scenes.splice(from,1)[0]);this.dirty=true;this.render();};
  }
  async save(){
    const profiles=structuredClone(this.data.profiles),snapshot=JSON.stringify(profiles);
    const task=(this.saveQueue||Promise.resolve()).then(async()=>{
      const value=await this.request('/api/build/profiles',{version:1,profiles,expectedRevision:this.data.revision},'PUT');
      this.data.revision=value.revision;this.data.file=value.file;
      this.dirty=JSON.stringify(this.data.profiles)!==snapshot;
      if(!this.disposed)this.element.querySelector('footer>span').textContent=this.dirty?'저장하지 않은 변경':'';
    });this.saveQueue=task.catch(()=>{});return task;
  }
  renderJob(){if(!this.job)return;const job=this.job;this.element.querySelector('.build-progress').textContent=job.status==='running'?job.stage+'…':job.status==='done'?'완료':job.status==='canceled'?'취소됨':'실패';const result=this.element.querySelector('.build-result');result.textContent=job.error||(!job.result?'':`${job.result.files}개 콘텐츠 · C++ ${job.result.nativeModules}개\n시작: ${job.result.startupScene}\n${job.result.executable||'검사 통과'}`);}
  async poll(){clearTimeout(this.timer);try{this.job=await this.request('/api/build/job?id='+this.job.id);if(this.disposed)return;if(this.job.status==='running'){this.renderJob();this.timer=setTimeout(()=>this.poll(),500);}else{this.render();if(this.runAfterBuild&&this.job.status==='done'){this.runAfterBuild=false;await this.request('/api/build/open',{id:this.job.id,action:'run'});}}}catch(error){this.hooks.error(error);}}
  dispose(){window.removeEventListener('beforeunload',this.unload);this.disposed=true;clearTimeout(this.timer);}
}
